1	import type { createClient } from "@/lib/supabase/server";
2	
3	type SupabaseServerClient = Awaited<ReturnType<typeof createClient>>;
4	
5	export type SubscriptionAccess = {
6	  locked: boolean;
7	  status: "unpaid" | "active" | "past_due" | "expired";
8	  planCode: string | null;
9	  periodEnd: string | null;
10	};
11	
12	// `unpaid` (no subscription row yet, or never paid) and `expired` (lapsed
13	// past the grace period) block access; `active` and `past_due` don't —
14	// past_due only shows a warning banner, per the grace-period design.
15	export async function getSubscriptionAccess(
16	  supabase: SupabaseServerClient,
17	  businessId: string,
18	): Promise<SubscriptionAccess> {
19	  const { data } = await supabase
20	    .from("subscriptions")
21	    .select("plan_code, status, period_end")
22	    .eq("business_id", businessId)
23	    .maybeSingle();
24	
25	  if (!data) {
26	    return { locked: true, status: "unpaid", planCode: null, periodEnd: null };
27	  }
28	
29	  const status = data.status as SubscriptionAccess["status"];
30	  return {
31	    locked: status === "unpaid" || status === "expired",
32	    status,
33	    planCode: data.plan_code,
34	    periodEnd: data.period_end,
35	  };
36	}
