6	export default async function BusinessDashboardLayout({
7	  children,
8	  params,
9	}: {
10	  children: React.ReactNode;
11	  params: Promise<{ businessId: string }>;
12	}) {
13	  const { businessId } = await params;
14	  const supabase = await createClient();
15	
16	  const [{ data: business }, { data: userData }, access] = await Promise.all([
17	    supabase.from("businesses").select("id, name, business_type").eq("id", businessId).single(),
18	    supabase.auth.getUser(),
19	    getSubscriptionAccess(supabase, businessId),
20	  ]);
21	
22	  if (!business) {
23	    notFound();
24	  }
25	
26	  if (access.locked) {
27	    redirect(`/business/${businessId}/billing`);
28	  }
29	
30	  return (
31	    <DashboardShell
32	      businessId={businessId}
33	      businessName={business.name}
34	      businessType={business.business_type as "fnb" | "retail" | "tiket"}
35	      userEmail={userData.user?.email ?? ""}
36	      billingPastDuePeriodEnd={access.status === "past_due" ? access.periodEnd : null}
37	    >
38	      {children}
39	    </DashboardShell>
40	  );
41	}
