19	// Kalkulator HPP Desktop — pesanan sekali-beli tanpa akun/business_id sama
20	// sekali (lihat 20260713130000_hpp_desktop_orders.sql). Order ID-nya diberi
21	// prefix "HPP-" (dibuat di kalkulator-hpp/beli/actions.ts) supaya bisa
22	// dibedakan dari order langganan bisnis ("KK-...") di webhook yang sama —
23	// Midtrans hanya punya satu URL notifikasi per akun, jadi ini tidak bisa
24	// dipecah jadi route terpisah.
25	async function handleDesktopOrderNotification(
26	  supabase: ReturnType<typeof createServiceClient>,
27	  body: MidtransNotification,
28	) {
29	  const { data: order } = await supabase
30	    .from("hpp_desktop_orders")
31	    .select("id, status")
32	    .eq("order_id", body.order_id)
33	    .maybeSingle();
