65	export async function POST(request: Request) {
66	  const body = (await request.json()) as MidtransNotification;
67	
68	  const serverKey = process.env.MIDTRANS_SERVER_KEY;
69	  if (!serverKey) {
70	    return NextResponse.json({ error: "not configured" }, { status: 500 });
71	  }
72	
73	  const expectedSignature = createHash("sha512")
74	    .update(`${body.order_id}${body.status_code}${body.gross_amount}${serverKey}`)
75	    .digest("hex");
76	
77	  if (expectedSignature !== body.signature_key) {
78	    return NextResponse.json({ error: "invalid signature" }, { status: 401 });
79	  }
80	
81	  const supabase = createServiceClient();
82	
83	  if (body.order_id.startsWith("HPP-")) {
84	    return handleDesktopOrderNotification(supabase, body);
85	  }
86	
87	  const { data: payment } = await supabase
88	    .from("payments")
89	    .select("id, business_id, plan_code, status")
90	    .eq("order_id", body.order_id)
91	    .maybeSingle();
92	
93	  if (!payment) {
94	    // Unknown order_id — nothing to do, but still ack so Midtrans stops retrying.
95	    console.error(`Midtrans notification for unknown order_id: ${body.order_id}`);
96	    return NextResponse.json({ ok: true });
97	  }
98	
99	  if (payment.status === "settlement") {
100	    // Already processed — Midtrans retries notifications, this is expected.
101	    return NextResponse.json({ ok: true });
102	  }
103	
104	  const newPaymentStatus = SETTLED_STATUSES.has(body.transaction_status)
105	    ? "settlement"
106	    : FAILED_STATUSES.has(body.transaction_status)
107	      ? body.transaction_status
108	      : "pending";
109	
110	  await supabase
111	    .from("payments")
112	    .update({
113	      status: newPaymentStatus,
114	      midtrans_transaction_id: body.transaction_id ?? null,
115	      payment_type: body.payment_type ?? null,
116	      raw_notification: body,
117	    })
118	    .eq("id", payment.id);
119	
120	  if (newPaymentStatus !== "settlement") {
121	    return NextResponse.json({ ok: true });
122	  }
123	
124	  const plan = getPlan(payment.plan_code);
125	  if (!plan) {
126	    console.error(`Settled payment references unknown plan_code: ${payment.plan_code}`);
127	    return NextResponse.json({ ok: true });
128	  }
129	
130	  let newPeriodEnd: string | null = null;
131	  if (plan.periodDays !== null) {
132	    const { data: subscription } = await supabase
133	      .from("subscriptions")
134	      .select("period_end")
135	      .eq("business_id", payment.business_id)
136	      .maybeSingle();
137	
138	    const now = Date.now();
139	    const currentPeriodEnd = subscription?.period_end
140	      ? new Date(subscription.period_end).getTime()
141	      : 0;
142	    const base = Math.max(now, currentPeriodEnd);
143	    newPeriodEnd = new Date(base + plan.periodDays * 24 * 60 * 60 * 1000).toISOString();
144	  }
145	
146	  await supabase
147	    .from("subscriptions")
148	    .update({
149	      plan_code: plan.code,
150	      status: "active",
151	      period_end: newPeriodEnd,
152	      updated_at: new Date().toISOString(),
153	    })
154	    .eq("business_id", payment.business_id);
155	
156	  return NextResponse.json({ ok: true });
157	}
